import type { KioskPublicState } from '@shul-store/shared';

const CATEGORIES = [
  { id: 'c1', name: 'Grocery', secondaryName: null },
  { id: 'c2', name: 'Beverages', secondaryName: null },
  { id: 'c3', name: 'Bakery', secondaryName: null },
  { id: 'c4', name: 'Judaica', secondaryName: null },
];

const PRODUCTS = [
  ['Matzo Ball Mix 4.5oz', 'c1', 329],
  ['Pure Clover Honey 12oz', 'c1', 599],
  ['Mini Soup Croutons 5oz', 'c1', 149],
  ['Grape Juice 64oz', 'c2', 699],
  ['Potato Kugel Mix 6oz', 'c1', 299],
  ['Chocolate Wafers 9oz', 'c3', 379],
  ['Puffed Wheat Cereal 14oz', 'c1', 429],
  ['Rugelach Assorted 12oz', 'c3', 649],
  ['Babka Chocolate Loaf', 'c3', 899],
  ['Shabbos Candles 72ct', 'c4', 1299],
  ['Cherry Cola 2L', 'c2', 249],
  ['Selzer Original 1L', 'c2', 149],
].map(([name, categoryId, price], i) => ({
  id: `p${i + 1}`,
  categoryId,
  name,
  secondaryName: null,
  priceCents: price,
  imageId: null,
  barcodes: [`0702270020${i}`],
}));

const LOGO =
  'data:image/png;base64,';

const STATE = {
  connection: 'online' as
    'unpaired' | 'online' | 'manager-unreachable' | 'revoked',
  host: '192.168.1.24',
  port: 4141,
  kioskId: 'k1',
  kioskName: 'Lobby kiosk',
  storeName: 'BM Flatbush — Canteen',
  catalog: {
    storeName: 'BM Flatbush — Canteen',
    storeLogoDataUrl: LOGO,
    categories: CATEGORIES,
    products: PRODUCTS,
  } as {
    storeName: string;
    storeLogoDataUrl: string;
    categories: typeof CATEGORIES;
    products: typeof PRODUCTS;
  } | null,
  tokenPersistenceWarning: false,
  inFlightCharge: null,
  adminLockedUntil: null,
  discoveredManagers: [] as {
    storeName: string;
    host: string;
    port: number;
    lastSeenAt: number;
  }[],
  readerStatus: {
    configured: true,
    connected: true,
    label: 'BBPOS WisePOS E',
    processorId: 'cardknox-bbpos',
  },
  googleSignInAvailable: false,
};

const api = {
  getState: () => Promise.resolve(STATE),
  pair: () => Promise.resolve(STATE),
  refreshCatalog: () => Promise.resolve(STATE),
  priceCart: (lines: { productId: string; quantity: number }[]) => {
    const quoteLines = lines.map((l) => {
      const p = PRODUCTS.find((x) => x.id === l.productId);
      const unit = (p?.priceCents ?? 0) as number;
      const sub = unit * l.quantity;
      return {
        productId: l.productId,
        quantity: l.quantity,
        unitPriceCents: unit,
        subtotalCents: sub,
        taxCents: 0,
        totalCents: sub,
        name: p?.name ?? 'Item',
        secondaryName: null,
      };
    });
    const subtotalCents = quoteLines.reduce((s, l) => s + l.subtotalCents, 0);
    return Promise.resolve({
      ok: true,
      quote: {
        lines: quoteLines,
        subtotalCents,
        taxCents: 0,
        totalCents: subtotalCents,
      },
    });
  },
  charge: () => Promise.resolve({ ok: true }),
  benefitCharge: () => Promise.resolve({ ok: true }),
  scaleGetStatus: () =>
    Promise.resolve({ mode: 'simulated', connected: true, error: null }),
  scaleReadWeight: () =>
    Promise.resolve({ weightKg: 1.25, stable: true, timestamp: '' }),
  scaleStart: () => Promise.resolve(),
  scaleStop: () => Promise.resolve(),
  subscribeScale: () => () => undefined,
  subscribeScaleStatus: () => () => undefined,
  verifyAdminPin: (pin: string) =>
    Promise.resolve(
      pin === '1234' ? { ok: true } : { ok: false, message: 'Wrong PIN' },
    ),
  exitKiosk: () => Promise.resolve(),
  restart: () => Promise.resolve(),
  startDiscovery: () => Promise.resolve(),
  stopDiscovery: () => Promise.resolve(),
  cloudSignIn: () => Promise.resolve(STATE),
  cloudSignInWithGoogle: () => Promise.resolve(STATE),
  getReaderStatus: () => Promise.resolve(STATE.readerStatus),
  saveReaderConfig: () => Promise.resolve(STATE.readerStatus),
  pairUsaepayDevice: () =>
    Promise.resolve({ deviceKey: 'dk', pairingCode: '1234', expiresAt: '' }),
  checkReader: () => Promise.resolve({ ok: true, message: 'Reader ready' }),
  getExplanationDismissed: () => Promise.resolve(false),
  dismissExplanation: () => Promise.resolve(),
  updates: {
    check: () =>
      Promise.resolve({
        status: 'up_to_date',
        currentVersion: '0.2.9',
        availableVersion: null,
        message: 'Up to date',
        checkedAt: null,
      }),
    getState: () =>
      Promise.resolve({
        status: 'up_to_date',
        currentVersion: '0.2.9',
        availableVersion: null,
        message: 'Up to date',
        checkedAt: null,
      }),
    subscribe: () => () => undefined,
  },
  subscribe: () => () => undefined,
};

// Swaps window.kioskApi for the in-memory demo and returns the paired demo
// state. Used by demo.html and by the in-app "Explore the demo" link so a
// store (or a Store reviewer) can try the kiosk without pairing a manager.
const PAIRED_STATE = { ...STATE };

export function installDemoApi(
  startUnpaired = new URLSearchParams(location.search).has('pairing'),
): KioskPublicState {
  // The demo page passes ?pairing to render the unpaired setup screens
  // instead of the attract screen; the in-app demo link forces `false`.
  // Restore the paired defaults first so repeat calls stay predictable.
  Object.assign(STATE, PAIRED_STATE);
  if (startUnpaired) {
    STATE.connection = 'unpaired';
    STATE.catalog = null;
    STATE.storeName = '';
    STATE.googleSignInAvailable = true;
    STATE.discoveredManagers = [
      {
        storeName: 'BM Flatbush — Canteen',
        host: '192.168.1.24',
        port: 4141,
        lastSeenAt: Date.now(),
      },
    ];
  }
  (window as unknown as { kioskApi: unknown }).kioskApi = api;
  return STATE as unknown as KioskPublicState;
}
